    cpp: `#include <bits/stdc++.h>\nusing namespace std;\n\nint solve() {\n    // TODO: fix the bug in this debugging exercise.\n    ${seed.code.split('\n').slice(0, 4).join('\n').replace(/\n/g, '\n    ')}\n    return 0;\n}\n\nint main() { return solve(); }\n`,
    c: `#include <stdio.h>\n\nint solve() {\n    // TODO: fix the bug in this debugging exercise.\n    ${seed.code.split('\n').slice(0, 4).join('\n').replace(/\n/g, '\n    ')}\n    return 0;\n}\n\nint main() { return solve(); }\n`
